 const el=id=>document.getElementById(id);
 const dialog=(id,title,content)=>`<dialog id="${id}-dialog" class="modal upgrade-modal"><div class="modal-heading"><div><span class="eyebrow">ODDSSCOUT / RESEARCH TOOLS</span><h2>${title}</h2></div><button class="icon-btn" data-close="${id}-dialog" aria-label="Close ${title}">×</button></div>${content}</dialog>`;
 let prefs=saved('os-personalization',{teams:[],players:[],leagues:[],sports:[]}),ticket=[],center=null,centerMarket='h2h',centerGroup=null,movements=[],centerSeq=0,askSeq=0,playerStatsSeq=0,centerUnavailable=true;
