 dialog('markets','Explore more markets',`<p>Player props, team props and alternate lines load only for the game you choose. Available markets depend on your provider plan and the reporting sportsbook.</p><label for="market-game">Choose a loaded game</label><select id="market-game"></select><button class="button primary full-width" id="market-open-game">Open Game Center markets ↗</button><p class="small-print">In Game Center, use the Market menu to request one market at a time. Unsupported or suspended prices stay unavailable.</p><h3>Futures</h3><p>Browse the provider’s active futures catalog. No scheduled game or result is invented for an outright market.</p><div id="futures-options" class="futures-options"></div>`)+
 dialog('player-stats','Player Stats',`<p>Look up real completed-game results by full player name. MLB data comes from MLB StatsAPI; NBA, NFL and NHL data comes from ESPN publisher game logs. Each result is checked against a final game. Missing results stay unavailable.</p><form id="player-stats-form"><label for="player-stats-league">League</label><select id="player-stats-league"><option value="americanfootball_nfl">NFL</option><option value="basketball_nba">NBA</option><option value="baseball_mlb">MLB</option><option value="icehockey_nhl">NHL</option></select><label for="player-stats-name">Full player name</label><input id="player-stats-name" maxlength="100" minlength="2" autocomplete="off" placeholder="Enter the exact full name" required><label for="player-stats-stat">Statistic</label><select id="player-stats-stat"></select><label for="player-stats-window">Completed appearances</label><select id="player-stats-window"><option value="5">Last available 5</option><option value="10">Last available 10</option><option value="20">Last available 20</option></select><label for="player-stats-line">Optional comparison line</label><input id="player-stats-line" type="number" min="0" max="10000" step="0.001" inputmode="decimal" placeholder="Leave blank to see averages and results"><button class="button primary full-width" id="player-stats-submit">Load real player results ↗</button></form><div id="player-stats-results" role="status" aria-live="polite"><p class="muted">Choose a league, player and statistic to begin. No sample results are preloaded.</p></div>`)+
 dialog('preferences','Your lineup',`<p>Favorites move relevant games higher on your dashboard. They never change probabilities, prices, or research scores.</p><form id="preferences-form"><label for="pref-teams">Favorite teams (one per line)</label><textarea id="pref-teams" rows="3" maxlength="1200" placeholder="Cleveland Browns\nCleveland Cavaliers"></textarea><label for="pref-players">Favorite players (one per line)</label><textarea id="pref-players" rows="2" maxlength="1200" placeholder="Players you follow"></textarea><label for="pref-leagues">Favorite leagues (one per line)</label><textarea id="pref-leagues" rows="2" maxlength="600" placeholder="NFL\nNBA"></textarea><label for="pref-sports">Favorite sports (one per line)</label><textarea id="pref-sports" rows="2" maxlength="600" placeholder="American Football&#10;Basketball"></textarea><button class="button primary full-width">Save preferences</button></form><button class="button full-width" data-open="settings">Choose My Sportsbooks ↗</button><div id="registry-coverage"></div>`)+
 dialog('responsible','Keep perspective',`<p>21+ where required. Set a limit you can afford to lose, take regular breaks, and never chase losses. An attractive price does not remove risk.</p><form id="budget-form"><label for="budget-value">Monthly stake reminder ($)</label><input type="number" id="budget-value" min="0" max="100000" step="1" inputmode="decimal"><button class="button full-width">Save reminder</button></form><p class="small-print">This reminder uses self-reported stakes in My Bets. It cannot enforce limits in a sportsbook.</p><div id="break-status"></div><button class="button full-width" id="take-break">Take a 24-hour break from research</button><p>Ohio: <a href="tel:18005899966">1-800-589-9966</a> · <a href="https://timeoutohio.com/" target="_blank" rel="noopener noreferrer">Time Out Ohio</a></p><p>National: <a href="https://www.ncpgambling.org/help-treatment/" target="_blank" rel="noopener noreferrer">1-800-MY-RESET and support resources</a></p><p class="small-print">Breaks are stored on this browser. Support and your saved history remain accessible.</p>`)+
 dialog('community','Trending with users',`<p>Popularity is a separate count of signed-in users who liked a selection. It never enters statistical analysis or changes probabilities.</p><button class="button" id="community-refresh">Load community activity ↻</button><div id="community-content"></div>`);
 el('pref-teams').value=prefs.teams.join('\n');el('pref-players').value=prefs.players.join('\n');el('pref-leagues').value=prefs.leagues.join('\n');el('pref-sports').value=prefs.sports.join('\n');el('budget-value').value=limit||'';
 const playerStatsFields={americanfootball_nfl:[['passing_yards','Passing yards'],['passing_touchdowns','Passing touchdowns'],['rushing_yards','Rushing yards'],['rushing_touchdowns','Rushing touchdowns'],['receiving_yards','Receiving yards'],['receptions','Receptions'],['receiving_touchdowns','Receiving touchdowns']],basketball_nba:[['pts','Points'],['reb','Rebounds'],['ast','Assists'],['fg3m','Three-pointers made'],['pts_reb_ast','Points + rebounds + assists'],['stl','Steals'],['blk','Blocks'],['turnover','Turnovers']],baseball_mlb:[['hits','Hits'],['runs','Runs scored'],['rbi','Runs batted in'],['hr','Home runs'],['total_bases','Total bases'],['stolen_bases','Stolen bases'],['p_k','Pitcher strikeouts'],['pitching_outs','Pitching outs']],icehockey_nhl:[['goals','Goals'],['assists','Assists'],['points','Points'],['shots_on_goal','Shots on goal'],['saves','Goalie saves']]};
 function updatePlayerStatsFields(){el('player-stats-stat').innerHTML=playerStatsFields[el('player-stats-league').value].map(([value,label])=>`<option value="${value}">${label}</option>`).join('');}
 updatePlayerStatsFields();
 async function searchPlayerStats(){
  const seq=++playerStatsSeq,target=el('player-stats-results'),button=el('player-stats-submit');
  if(paused()){target.textContent='Player research is paused during your research break. Your saved history remains available.';return;}
  const params=new URLSearchParams({league:el('player-stats-league').value,player:el('player-stats-name').value.trim(),statType:el('player-stats-stat').value,window:el('player-stats-window').value,provider:'public'}),lineRaw=el('player-stats-line').value;
  if(lineRaw!=='')params.set('line',lineRaw);
  target.textContent='Checking the real player identity, results and final game statuses…';button.disabled=true;
  try{
   const data=await api('/api/performance?'+params,{signal:AbortSignal.timeout(45000)});if(seq!==playerStatsSeq)return;
   if(data.mode!=='live'||data.kind!=='player'||!Array.isArray(data.rows)||typeof data.source!=='string')throw new Error('The player-results response could not be verified. No substitute data was loaded.');
   const summary=data.summary||{},n=Number(summary.sampleSize)||0,format=value=>typeof value==='number'&&Number.isFinite(value)?String(Math.round(value*100)/100):'Unavailable';
   const compare=typeof data.line==='number'?`<p>Against ${esc(data.line)}: ${Number(summary.over)||0} above, ${Number(summary.under)||0} below, ${Number(summary.push)||0} equal. These describe past outcomes against this entered line.</p>`:'';
   target.innerHTML=`<h3>${esc(data.player?.name||params.get('player'))}</h3><p>${esc(data.source)} · fetched ${esc(new Date(data.fetchedAt).toLocaleString())}</p><p>${esc(data.sampleScope||'Returned completed-game sample.')}</p><div class="education-metrics"><div><span>Verified appearances</span><strong>${n} / ${esc(params.get('window'))}</strong></div><div><span>Sample average</span><strong>${esc(format(summary.average))}</strong></div><div><span>Sample minimum</span><strong>${esc(format(summary.min))}</strong></div><div><span>Sample maximum</span><strong>${esc(format(summary.max))}</strong></div></div>${summary.partial?'<p class="research-alert">Partial sample. Fewer verified appearances were returned than requested, or some source results could not be checked.</p>':''}${n?`<div class="performance-bars">${data.rows.map(row=>`<div><span>${esc(new Date(row.date).toLocaleDateString())}<small> ${esc(row.homeAway==='home'?'vs':'at')} ${esc(row.opponent)}</small></span><strong>${esc(row.value)}</strong></div>`).join('')}</div>`:'<p class="research-alert">No verified completed appearances were available for this player and statistic. No zeroes or sample games were inserted.</p>'}${compare}<p class="small-print">${esc(data.sourceSelection||'')} ${esc((data.limitations||[]).join(' '))}</p>`;
  }catch(error){if(seq===playerStatsSeq)target.textContent=`Player statistics unavailable. ${error.message}`;}
  finally{if(seq===playerStatsSeq)button.disabled=false;}
 }
 function priority(e){const text=`${e.home_team||''} ${e.away_team||''}`.toLowerCase(),group=(state.sports.find(s=>s.key===e.sport_key)?.group||'').toLowerCase(),players=(e.bookmakers||[]).flatMap(b=>(b.markets||[]).flatMap(m=>(m.outcomes||[]).map(o=>o.description||''))).join(' ').toLowerCase();return prefs.teams.filter(t=>text.includes(t.toLowerCase())).length*2+prefs.leagues.filter(l=>(e.sport_title||e.sport_key).toLowerCase().includes(l.toLowerCase())).length+prefs.sports.filter(s=>group.includes(s.toLowerCase())).length+prefs.players.filter(p=>players.includes(p.toLowerCase())).length;}
 function selectionButtons(e,g){return `<div class="selection-tools"><button class="text-button" data-lab-add="${esc(e.id)}" data-lab-group="${esc(g.id)}" data-lab-market="${esc(g.market)}" data-lab-source="${e===center?'center':'board'}" ${!g.best||(e===center?centerDataBlocked():blocked())?'disabled':''}>+ Add to parlay</button><button class="text-button" data-community-like="${esc(e.id)}" data-community-group="${esc(g.id)}" data-community-market="${esc(g.market)}">👍 Community like</button></div>`;}
 function update(){
  const events=state.board?.events||[],groups=blocked()?[]:events.flatMap(e=>compareGroups(e,state.market,{bookKeys:state.bookKeys}).map(g=>({event:e,group:g}))).filter(x=>x.group.best&&x.group.comparable);
  const bySelection=new Map();for(const sample of (state.board?.movementSamples||[]).slice(-10000)){const key=JSON.stringify([sample.eventId,sample.groupId]);if(!bySelection.has(key))bySelection.set(key,[]);bySelection.get(key).push(sample);}
  const movers=[];for(const {event,group} of groups){const history=bySelection.get(JSON.stringify([event.id,group.id]))||[];if(history.length<2)continue;const observed=lineMovement(history,{eventId:event.id,groupId:group.id});for(const series of observed.series){const currentQuote=group.freshQuotes.find(q=>q.book===series.book);if(series.points.length<2||!currentQuote||series.current.timestamp!==currentQuote.updatedAt)continue;const delta=series.current.impliedProbability-series.firstObserved.impliedProbability;if(Math.abs(delta)>1e-8)movers.push({event,group,series,delta});}}const mover=movers.sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta))[0];
  const best=groups.sort((a,b)=>(b.group.best.price-b.group.worst.price)-(a.group.best.price-a.group.worst.price))[0];
  const games=events.filter(e=>e.kind!=='future'),marketSelected=el('market-game').value;el('market-game').innerHTML=games.map(e=>`<option value="${esc(e.id)}">${esc(eventTitle(e))}</option>`).join('')||'<option value="">No loaded games available</option>';if(games.some(e=>e.id===marketSelected))el('market-game').value=marketSelected;else if(games.some(e=>e.id===state.selectedId))el('market-game').value=state.selectedId;el('market-open-game').disabled=!games.length||paused();el('futures-options').innerHTML=(state.futures||[]).map(f=>`<button class="button" data-future-league="${esc(f.key)}">${esc(f.title)} ↗</button>`).join('')||'<p class="muted">No active futures catalog has loaded. Connect the provider to check coverage.</p>'; 
  const count=new Set(events.flatMap(e=>(e.bookmakers||[]).map(b=>b.key))).size;
  el('dash-cards').innerHTML=`<article class="dash-card"><span class="eyebrow">BEST PRICES RIGHT NOW</span><strong>${best?esc(formatOdds(best.group.best.price,state.format)):'—'}</strong><p>${best?`${esc(groupLabel(best.group))}<br>${esc(best.group.best.title)} · ${esc(timeAgo(best.group.best.updatedAt))}`:'Waiting for fresh, comparable prices.'}</p>${best?`<button class="text-button" data-center="${esc(best.event.id)}">See comparison ↗</button>`:'<button class="text-button" data-retry>Check connection ↗</button>'}</article><article class="dash-card"><span class="eyebrow">BIGGEST OBSERVED PRICE MOVE</span><strong>${mover?Math.abs(mover.delta*100).toFixed(1)+' pp':'—'}</strong><p>${mover?`${esc(groupLabel(mover.group))}<br>${esc(mover.series.title)} · since first observation`:'Collecting source-dated history. No opening prices are inferred.'}</p>${mover?`<button class="text-button" data-center="${esc(mover.event.id)}">Inspect movement ↗</button>`:'<button class="text-button" data-retry>Refresh observations ↗</button>'}</article><article class="dash-card"><span class="eyebrow">YOUR SPORTSBOOKS</span><strong>${count}<small> reporting</small></strong><p>${state.myBooks.length} accounts selected<br>Coverage comes from the live provider.</p><button class="text-button" data-open="preferences">Manage your lineup ↗</button></article><article class="dash-card"><span class="eyebrow">RECENT PERFORMANCE</span><strong>Real data<small> only</small></strong><p>Team form and player histories load when you request them.</p><button class="text-button" data-open="player-stats">Player Stats ↗</button><br><button class="text-button" data-open="research">Team form ↗</button></article><article class="dash-card"><span class="eyebrow">POPULARITY / SEPARATE</span><strong>${communityLoaded?community.length:'—'}<small> selections</small></strong><p>${communityLoaded?'Actual user activity. It is not model analysis.':'No community activity loaded.'}</p><button class="text-button" data-open="community">Trending with users ↗</button></article>`;
  document.querySelectorAll('[data-book-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.bookMode===state.bookMode);b.setAttribute('aria-pressed',String(b.dataset.bookMode===state.bookMode));});
  el('scout-context').textContent=scoutContextMode==='center'&&center?`${eventTitle(center)} · ${mkName(centerMarket)} · ${ticket.length} parlay legs${centerUnavailable?' · game feed unavailable':''}`:state.board?.events.find(e=>e.id===state.selectedId)?`${state.board.events.find(e=>e.id===state.selectedId).away_team} at ${state.board.events.find(e=>e.id===state.selectedId).home_team} · selected board market`:'Education · no game selected';
  const returnedBooks=new Map(events.flatMap(e=>(e.bookmakers||[]).map(b=>[b.key,b.title]))),reported=new Set(returnedBooks.keys());
  const registry=[...SPORTSBOOKS,...[...returnedBooks].filter(([key])=>!SPORTSBOOKS.some(b=>b.id===resolveSportsbook(key).id)).map(([key,title])=>resolveSportsbook(key,title))];
  el('registry-coverage').innerHTML='<h3>Sportsbook coverage</h3><p class="small-print">Marks identify books; they are app-created monograms. State availability is documented separately from provider coverage. Confirm current eligibility with each operator.</p>'+registry.map(b=>{const key=b.providerKey||b.id;return `<div class="registry-row"><img src="${esc(b.logo)}" width="36" height="36" alt="${esc(b.name)} mark" loading="lazy"><div><strong>${esc(b.name)}</strong><small>${esc(availabilityLabel(b))}</small></div><span class="${reported.has(key)?'positive':'muted'}">${reported.has(key)?'Provider reporting':b.providerKey?'No current feed quote':'Provider unsupported'}</span></div>`;}).join('');
  el('break-status').textContent=paused()?`Research break active until ${new Date(breakUntil).toLocaleString()}. Your history and support remain available.`:'No research break active.';
  document.body.classList.toggle('research-paused',paused());el('take-break').disabled=paused();
  el('research-break-banner').classList.toggle('hidden',!paused());el('research-break-banner').innerHTML=paused()?`<div><strong>Your research break is active</strong><p>Until ${esc(new Date(breakUntil).toLocaleString())}. Saved history, education and support remain available.</p></div><button class="button" data-open="responsible">Support & limits ↗</button>`:'';
  el('community-content').innerHTML=communityLoaded?community.map(c=>`<article class="community-row"><strong>${esc(c.title)}</strong><p>${Number(c.likes)||0} likes · popularity only · ${esc(timeAgo(c.latest_like))}</p></article>`).join('')||'<p>No recorded community likes yet.</p>':`<p class="muted">${esc(communityError)}</p>`;
  if(limit){const month=new Date();month.setDate(1);month.setHours(0,0,0,0);const risked=tracker.records().filter(r=>r.mode==='real'&&r.placedAt&&Date.parse(r.placedAt)>=+month).reduce((s,r)=>s+(r.stake||0),0);if(risked>=limit)el('dash-cards').insertAdjacentHTML('afterbegin',`<article class="dash-card budget-warning"><span class="eyebrow">YOUR LIMIT REMINDER</span><strong>${money(risked)}</strong><p>Recorded this month, against your ${money(limit)} reminder.</p><button class="text-button" data-open="responsible">Take a break or find support ↗</button></article>`);}
  renderTicket();renderJournal();refreshCenterView();
 }
 function resolveTicket(){return ticket.map(l=>({...l,event:state.board?.events.find(e=>e.id===l.event.id)||l.event}));}
 function renderTicket(){
  ticket=resolveTicket();el('ticket-dock').classList.toggle('hidden',!ticket.length);el('ticket-count').textContent=`${ticket.length} legs`;
  el('lab-legs').innerHTML=ticket.length?ticket.map((l,i)=>{const g=compareGroups(l.event,l.market).find(g=>g.id===l.groupId);return `<div class="ticket-leg"><div><strong>${esc(g?groupLabel(g):l.label)}</strong><small>${esc(eventTitle(l.event))}</small></div><button class="icon-btn" data-lab-remove="${i}" aria-label="Remove ${esc(l.label)}">×</button></div>`;}).join(''):'<div class="lab-empty"><span>＋</span><h3>Build from the data.</h3><p>Add fresh selections from the board or Game Center. A ticket compares only books that quote every leg.</p></div>';
  const stake=Number(el('lab-stake').value),valid=el('lab-stake').value!==''&&Number.isFinite(stake)&&stake>=0&&stake<=100000;
  const c=blocked()?{ok:false,reason:paused()?'Research is paused during your break.':'Connect the live feed to compare this ticket.'}:analyzeParlay(ticket,{bookKeys:state.bookKeys,stake:valid?stake:0});
  el('lab-comparison').innerHTML=c.ok?`<div class="research-data-label">ESTIMATE · SINGLE-LEG PRICE PRODUCT</div>${c.books.map(b=>`<div class="parlay-book ${b.book===c.best.book?'best':''}"><div><strong>${esc(b.title)}</strong><small>${esc(timeAgo(b.oldestAt))} · every leg quoted</small></div><div><strong>${formatOdds(b.decimal,state.format)}</strong><small>${valid?`${money(stake)} → ${money(stake*b.decimal)}`:'Enter a valid stake'}</small></div></div>`).join('')}<p class="small-print">The combined price is an estimate, not an API-confirmed sportsbook offer. Correlated legs, settlement rules and market suspension can change eligibility and the accepted price. Joint model probability and model edge: unavailable.</p><button class="button" id="lab-save">Save ticket idea</button><button class="button" id="lab-copy">Copy ticket</button>`:`<p class="research-alert">${esc(c.reason||'Choose 2–4 separate-game selections.')}</p>`;
  el('lab-health').innerHTML=c.health?`<div class="health-box"><span class="eyebrow">PARLAY HEALTH / OBSERVED DATA</span><strong>${c.health.score===null?'Unavailable':`${Math.round(c.health.score)} / 100`}</strong><p>${esc(c.health.label)}</p><p class="small-print">${esc(c.health.warning)}</p><details><summary>Why this score?</summary><p>${esc(c.health.method)}</p>${c.health.factors.map(f=>`<div class="health-factor"><span>${esc(f.name)}</span><b>${f.value===null?'Unavailable':Math.round(f.value)}</b><small>${esc(f.explanation)} · weight ${f.weight}</small></div>`).join('')}<p>Missing: ${esc(c.health.unavailableDimensions.map(d=>typeof d==='string'?d:d.name).join(', '))}. This measures the observed research inputs, not a chance of winning.</p></details></div>`:'';
  education();
 }
 function education(){
  const raw=el('lab-probs').value.split(',').map(x=>x.trim()),nums=raw.map(x=>Number(x)/100);const stake=Number(el('lab-stake').value);
  if(!raw.length||raw.length>8||raw.some(x=>!x)||nums.some(n=>!Number.isFinite(n)||n<=0||n>=1)||!Number.isFinite(stake)||stake<0||stake>100000){el('lab-math').textContent='Enter 1–8 assumed probabilities between 0 and 100, and a valid stake.';return;}
  const r=educationalParlay(nums,stake);el('lab-math').innerHTML=`<div class="education-metrics"><div><span>Approx. combined chance</span><strong>${(r.combinedProbability*100).toFixed(2)}%</strong></div><div><span>Fair odds under these assumptions</span><strong>${formatOdds(r.fairDecimal,state.format)}</strong></div></div><p>${nums.map(n=>`${(n*100).toFixed(1)}%`).join(' × ')} = ${(r.combinedProbability*100).toFixed(2)}%. All ${nums.length} conditions must win. Independence is an assumption; a same-game parlay often violates it. Fair payout at these assumed probabilities: ${money(r.total)} including the ${money(stake)} stake. This is an educational calculation.</p>`;
 }
 async function add(id,gid,market,fromCenter=false){
  if(fromCenter&&center?.id!==id){toast('Refresh Game Center before adding this selection.');return;}
  if(fromCenter?centerDataBlocked():blocked()){toast(paused()?'Research is paused during your break.':'Load fresh provider data first.');return;}
  const event=(fromCenter?center:state.board?.events.find(e=>e.id===id));const group=event&&compareGroups(event,market,{bookKeys:state.bookKeys}).find(g=>g.id===gid);
  if(!group?.best){toast('No fresh price for this exact selection.');return;}
  if(ticket.length>=4){toast('This ticket supports up to four legs.');return;}
  if(ticket.some(l=>l.event.id===id)){toast('Same-game correlation needs a confirmed sportsbook quote. Choose another matchup.');return;}
  ticket.push({event,groupId:gid,market,label:groupLabel(group)});renderTicket();openModal('lab');
 }
