   if(bundle.mode!=='live'||!bundle.event||bundle.event.id!==id)throw new Error('The provider returned an invalid game snapshot. No substitute data was loaded.');center=bundle.event;centerUnavailable=false;movements=bundle.movementSamples||[];center.availableMarkets=bundle.availableMarkets||['h2h','spreads','totals'];center.limitations=bundle.limitations||[];center.fetchedAt=bundle.fetchedAt;
