 async function performance(){
  const g=centerGroups().find(g=>g.id===centerGroup);if(!g?.subject)return;
  if(centerDataBlocked()){toast('Refresh the game connection before loading player history.');return;}
  const statType=playerStatForMarket(center.sport_key,g.market);
  const target=el('player-history'),currentEvent=center.id,currentMarket=centerMarket,currentGroup=centerGroup,currentSeq=centerSeq;
  const current=()=>!!el('player-history')&&center?.id===currentEvent&&centerMarket===currentMarket&&centerGroup===currentGroup&&centerSeq===currentSeq;
  if(!statType){target.textContent='A matching recent-stat adapter is not available for this market. No hit history was invented.';return;}
  if(!['Over','Under'].includes(g.name)||typeof g.point!=='number'){target.textContent='Hit-rate history requires an exact numerical Over/Under line. No probability was inferred for this selection.';return;}
  target.textContent='Loading completed-game statistics…';
  try{
   const data=await api('/api/performance?'+new URLSearchParams({league:center.sport_key,player:g.subject,statType,line:String(g.point),window:'10'}));if(!current())return;
   const identity=value=>String(value||'').normalize('NFKD').toLocaleLowerCase().replace(/[^\p{L}\p{N}]/gu,'');if(data.mode!=='live'||data.kind!=='player'||data.league!==center.sport_key||data.statType!==statType||identity(data.player?.name)!==identity(g.subject)||!Array.isArray(data.rows)||typeof data.source!=='string'||!Number.isFinite(Date.parse(data.fetchedAt)))throw new Error('The source did not return verified results for this exact player and statistic.');
   const rows=data.rows||data.stats||[];const scope={line:g.point,direction:g.name,playerId:data.player?.id,statType:data.statType};const f=recentPerformance(rows,{...scope,limit:5});const ten=recentPerformance(rows,{...scope,limit:10});const analysis=candidateAnalysis(center,g,{bookKeys:state.bookKeys,performance:data});
   const source=typeof data.source==='string'?data.source:'Source unavailable';
   const sampleLabel=data.complete===false?'Partial returned sample':'Most recent available completed-game sample';
   const seasonAverage=typeof data.seasonAverage==='number'&&Number.isFinite(data.seasonAverage)?String(data.seasonAverage):'unavailable';
   el('player-history').innerHTML=`<p>${esc(source)} · fetched ${esc(Number.isFinite(Date.parse(data.fetchedAt))?new Date(data.fetchedAt).toLocaleString():'time unavailable')}</p>${f.unavailable?`<p class="research-alert">${esc(f.reason)}</p>`:`<p>${esc(sampleLabel)}. ${esc(data.sampleScope||'')}</p><div class="performance-bars">${f.rows.map(r=>`<div><span>${esc(new Date(r.date).toLocaleDateString())}</span><strong>${r.value}</strong><span>${r.result==='push'?'Push':r.result==='hit'?'✓ Hit':'Miss'}</span></div>`).join('')}</div><p>${data.complete===false?'First returned':'Last available'} ${f.games}: ${f.hits}/${f.games} hits${f.pushes?`, ${f.pushes} pushes`:''}. ${data.complete===false?'Returned':'Last available'} ${ten.games}: ${ten.hits}/${ten.games} hits${ten.pushes?`, ${ten.pushes} pushes`:''}. Season average: ${esc(seasonAverage)}. Opponent defensive rank and usage context: unavailable.</p>`}<p class="small-print">Descriptive history only. A recent hit rate is not a calibrated forecast. ${esc((data.limitations||[]).join(' '))}</p><details class="candidate-rationale"><summary>Why this candidate / what is missing?</summary><div class="candidate-context"><div><span>Market-implied chance</span><strong>${analysis.marketImpliedProbability===null?'Unavailable':(100*analysis.marketImpliedProbability).toFixed(1)+'%'}</strong></div><div><span>Model probability / edge</span><strong>Unavailable</strong></div></div><h4>Observed support</h4><ul>${analysis.why.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul><h4>Concerns</h4><ul>${analysis.concerns.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul><p class="small-print">${esc(analysis.rankingBasis)}</p></details>`;
  }catch(e){if(current())el('player-history').textContent=`Recent performance unavailable. ${e.message}`;}
 }
 async function scout(question){
  if(!question)return;const seq=++askSeq;el('scout-send').disabled=true;el('scout-answer').textContent='Reading the available context…';el('scout-source').textContent='';
  const useCenter=scoutContextMode==='center'&&center&&!centerUnavailable;const e=useCenter?center:state.board?.events.find(e=>e.id===state.selectedId);const body={question:question.slice(0,600),stake:state.stake,...(e&&(useCenter?!centerDataBlocked():!blocked())?{eventId:e.id,league:e.sport_key,market:useCenter?centerMarket:state.market,...((useCenter?centerGroup:state.groupId)?{groupId:useCenter?centerGroup:state.groupId}:{})}:{}),ticket:(paused()?[]:ticket).map(l=>({eventId:l.event.id,league:l.event.sport_key,groupId:l.groupId,market:l.market})),...(state.bookKeys?{bookKeys:state.bookKeys}:{})};
  try{const r=await api('/api/ask',{method:'POST',body:JSON.stringify(body)});if(seq!==askSeq)return;el('scout-answer').textContent=r.text;el('scout-source').textContent=`${r.mode==='ai'?'AI narration':'Rules-based education'} · ${r.note||''}${r.verified?.observedAt?` · snapshot ${r.verified.observedAt}`:''}`;}catch(e){if(seq===askSeq){el('scout-answer').textContent=e.message;el('scout-source').textContent='No answer was invented for failed live data.';}}finally{if(seq===askSeq)el('scout-send').disabled=false;}
 }
