 document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.open==='scout'){if(el('center-dialog').open)scoutContextMode='center';else if(el('compare-dialog').open)scoutContextMode='board';update();}
  if(b.dataset.bookMode){state.bookMode=b.dataset.bookMode;state.bookKeys=state.bookMode==='my'?state.myBooks:null;redraw();return;}
  if(b.dataset.day){state.date='today';state.status='all';state.view='board';el('date-range').value='today';redraw();el('board').scrollIntoView({behavior:'smooth'});return;}
  if(b.id==='market-open-game'){const id=el('market-game').value;if(id){el('markets-dialog').close();loadCenter(id);}return;}
  if(b.dataset.futureLeague){el('markets-dialog').close();changeScope?.(b.dataset.futureLeague,'outrights');el('board').scrollIntoView({behavior:'smooth'});return;}
  if(b.dataset.center){loadCenter(b.dataset.center);return;}
  if(b.hasAttribute('data-center-retry')){loadCenter(center.id,centerMarket,true);return;}
  if(b.dataset.labAdd){add(b.dataset.labAdd,b.dataset.labGroup,b.dataset.labMarket,b.dataset.labSource==='center');return;}
  if(b.dataset.labRemove!==undefined){ticket.splice(Number(b.dataset.labRemove),1);renderTicket();return;}
  if(b.dataset.scoutPrompt){openModal('scout');scout(b.dataset.scoutPrompt);return;}
  if(b.dataset.communityLike){like(b.dataset.communityLike,b.dataset.communityGroup,b.dataset.communityMarket);return;}
  if(b.hasAttribute('data-center-form')){if(centerDataBlocked()){toast('Refresh game data before loading recent scores.');return;}onOpenForm?.(center);return;}
  if(b.hasAttribute('data-center-save')){if(centerDataBlocked()){toast('Refresh the game connection before saving a new quote.');return;}const g=centerGroups().find(g=>g.id===centerGroup);try{await tracker.saveSelection(center,g);}catch(err){toast(err.message);}return;}
  if(b.hasAttribute('data-player-performance')){performance();return;}
  if(b.id==='lab-clear'){ticket=[];renderTicket();return;}
  if(b.id==='lab-save'){const c=analyzeParlay(resolveTicket(),{bookKeys:state.bookKeys});if(c.ok&&!blocked())await tracker.saveParlay(ticket,c);return;}
  if(b.id==='lab-copy'){const c=analyzeParlay(resolveTicket(),{bookKeys:state.bookKeys});if(!c.ok||blocked())return;try{await navigator.clipboard.writeText(`OddsScout research idea — not a placed bet\n${ticket.map(l=>l.label).join('\n')}\n${c.best.title}: estimated ${formatOdds(c.best.decimal,state.format)}. Verify combined price and rules in the book.`);toast('Ticket copied. Estimated price only.');}catch{toast('Clipboard unavailable. You can review the ticket here.');}return;}
  if(b.id==='community-refresh'){refreshCommunity();return;}
  if(b.id==='take-break'){breakUntil=Date.now()+86400000;persist('os-break-until',breakUntil);el('auto-refresh').checked=false;el('auto-refresh').dispatchEvent(new Event('change'));update();toast('Research break started. Your history and support remain available.');}
 });
